import React, { useState } from 'react'

import { ErrorMessage } from '@jbrowse/core/ui'
import DeleteIcon from '@mui/icons-material/Delete'
import {
  Button,
  IconButton,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Typography,
} from '@mui/material'
import { observer } from 'mobx-react'
import { makeStyles } from 'tss-react/mui'

import {
  featureMatchesId,
  getLinearGenomeView,
  getSortedTranscriptFeatures,
} from '../../util'
import { builtAlignmentLook, launchConnectedView } from '../launchConnectedView'
import { useLaunchPlacement } from '../launchPlacement'

import type { CachedBlastResult } from '../../../utils/blastCache'
import type { useCachedBlastResults } from './useCachedBlastResults'
import type { AbstractTrackModel, Feature } from '@jbrowse/core/util'

const useStyles = makeStyles()({
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 8,
  },
  resultList: {
    maxHeight: 300,
    overflow: 'auto',
  },
})

function getResultDisplayName(result: CachedBlastResult): string {
  const parts = [
    result.geneName,
    result.transcriptName !== result.geneName
      ? result.transcriptName
      : undefined,
  ].filter((p): p is string => !!p)
  return parts.length > 0
    ? parts.join(' - ')
    : (result.geneId ?? result.transcriptId ?? 'Unknown')
}

/**
 * How the row was produced: `uniprotkb_swissprot / blastp / clustalo`, or
 * `swissprot / phmmer` for a row phmmer aligned as it searched and that
 * therefore ran no aligner. Each part is dropped when absent rather than
 * printed empty — `msaAlgorithm` became optional when phmmer arrived, and a
 * phmmer row read `(undefined)` until this stopped assuming one.
 *
 * `blastProgram` is the older field, written only while the plugin still
 * queried NCBI directly and blastp/quick-blastp was a real choice.
 */
export function describeSearch(result: CachedBlastResult) {
  return [
    result.blastDatabase,
    result.searchProgram ?? result.blastProgram ?? 'blastp',
    result.msaAlgorithm,
  ]
    .filter(Boolean)
    .join(' / ')
}

const CachedBlastResults = observer(function ({
  model,
  handleClose,
  feature,
  cached: { results, handleDelete, handleClearAll },
}: {
  model: AbstractTrackModel
  handleClose: () => void
  feature: Feature
  /** the panel's own listing, so clearing it here empties it there too */
  cached: ReturnType<typeof useCachedBlastResults>
}) {
  const { classes } = useStyles()
  const view = getLinearGenomeView(model)
  const [operationError, setOperationError] = useState<unknown>()
  const [sideBySide] = useLaunchPlacement()

  const handleUseCached = (cached: CachedBlastResult) => {
    // the cached query row is the plugin's default `QUERY`, translated from
    // the transcript stored as transcriptId, so that transcript relinks it
    const { transcriptId, msa, tree, treeMetadata } = cached
    launchConnectedView({
      view,
      feature: transcriptId
        ? getSortedTranscriptFeatures(feature).find(t =>
            featureMatchesId(t, transcriptId),
          )
        : undefined,
      placement: sideBySide ? 'splitRight' : 'stack',
      displayName: `BLAST - ${getResultDisplayName(cached)}`,
      ...builtAlignmentLook,
      data: { msa, tree, treeMetadata },
    }).then(handleClose, (e: unknown) => {
      console.error(e)
      setOperationError(e)
    })
  }

  return (
    <div>
      {operationError ? <ErrorMessage error={operationError} /> : null}
      <div className={classes.header}>
        <Typography variant="subtitle1">
          Cached BLAST Results ({results.length})
        </Typography>
        <Button
          size="small"
          color="error"
          onClick={async () => {
            try {
              setOperationError(undefined)
              await handleClearAll()
            } catch (e) {
              setOperationError(e)
            }
          }}
        >
          Clear results for this gene
        </Button>
      </div>
      <List dense className={classes.resultList}>
        {results.map(result => (
          <ListItem
            key={result.id}
            disablePadding
            secondaryAction={
              <IconButton
                edge="end"
                size="small"
                onClick={async e => {
                  e.stopPropagation()
                  try {
                    setOperationError(undefined)
                    await handleDelete(result.id)
                  } catch (err) {
                    setOperationError(err)
                  }
                }}
              >
                <DeleteIcon fontSize="small" />
              </IconButton>
            }
          >
            <ListItemButton
              onClick={() => {
                handleUseCached(result)
              }}
            >
              <ListItemText
                primary={`${getResultDisplayName(result)} - ${describeSearch(result)}`}
                secondary={`${new Date(result.timestamp).toLocaleString()} - Seq: ${result.proteinSequence.slice(0, 30)}...`}
              />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    </div>
  )
})

export default CachedBlastResults
